	ListArticlesWithTagsForward(context.Context, *connect.Request[v1.ListArticlesWithTagsForwardRequest]) (*connect.Response[v1.ListArticlesWithTagsForwardResponse], error)
	// ListDeletedArticles returns deleted articles for syncing deletions.
	// Origin: services.backend.v1.BackendInternalService/ListDeletedArticles
	ListDeletedArticles(context.Context, *connect.Request[v1.ListDeletedArticlesRequest]) (*connect.Response[v1.ListDeletedArticlesResponse], error)
	// GetLatestArticleTimestamp returns the latest article created_at timestamp.
	// Origin: services.backend.v1.BackendInternalService/GetLatestArticleTimestamp
	GetLatestArticleTimestamp(context.Context, *connect.Request[v1.GetLatestArticleTimestampRequest]) (*connect.Response[v1.GetLatestArticleTimestampResponse], error)
	// GetArticleByID returns a single article with tags.
	// Origin: services.backend.v1.BackendInternalService/GetArticleByID
	GetArticleByID(context.Context, *connect.Request[v1.GetArticleByIDRequest]) (*connect.Response[v1.GetArticleByIDResponse], error)
	// CheckArticleExists checks if an article already exists by URL and feed.
	// Origin: services.backend.v1.BackendInternalService/CheckArticleExists
	CheckArticleExists(context.Context, *connect.Request[v1.CheckArticleExistsRequest]) (*connect.Response[v1.CheckArticleExistsResponse], error)
	// CreateArticle creates a new article and publishes ArticleCreated event.
	// Origin: services.backend.v1.BackendInternalService/CreateArticle
	CreateArticle(context.Context, *connect.Request[v1.CreateArticleRequest]) (*connect.Response[v1.CreateArticleResponse], error)
	// SaveArticleSummary saves an article summary.
	// Origin: services.backend.v1.BackendInternalService/SaveArticleSummary
	SaveArticleSummary(context.Context, *connect.Request[v1.SaveArticleSummaryRequest]) (*connect.Response[v1.SaveArticleSummaryResponse], error)
	// GetArticleContent returns article content for summarization.
	// Origin: services.backend.v1.BackendInternalService/GetArticleContent
	GetArticleContent(context.Context, *connect.Request[v1.GetArticleContentRequest]) (*connect.Response[v1.GetArticleContentResponse], error)
	// GetFeedID returns the feed ID for a given feed URL.
	// Origin: services.backend.v1.BackendInternalService/GetFeedID
	GetFeedID(context.Context, *connect.Request[v1.GetFeedIDRequest]) (*connect.Response[v1.GetFeedIDResponse], error)
	// ListFeedURLs returns feed URLs with cursor pagination.
	// Origin: services.backend.v1.BackendInternalService/ListFeedURLs
	ListFeedURLs(context.Context, *connect.Request[v1.ListFeedURLsRequest]) (*connect.Response[v1.ListFeedURLsResponse], error)
	// UpsertArticleTags upserts tags for an article.
	// Origin: services.backend.v1.BackendInternalService/UpsertArticleTags
	UpsertArticleTags(context.Context, *connect.Request[v1.UpsertArticleTagsRequest]) (*connect.Response[v1.UpsertArticleTagsResponse], error)
	// BatchUpsertArticleTags upserts tags for multiple articles.
	// Origin: services.backend.v1.BackendInternalService/BatchUpsertArticleTags
	BatchUpsertArticleTags(context.Context, *connect.Request[v1.BatchUpsertArticleTagsRequest]) (*connect.Response[v1.BatchUpsertArticleTagsResponse], error)
	// ListUntaggedArticles returns articles without tags.
	// Origin: services.backend.v1.BackendInternalService/ListUntaggedArticles
	ListUntaggedArticles(context.Context, *connect.Request[v1.ListUntaggedArticlesRequest]) (*connect.Response[v1.ListUntaggedArticlesResponse], error)
	// BatchGetTagsByArticleIDs returns tags for a batch of article ids.
	// Replaces tag-generator /api/v1/tags/batch (ADR-000241 / ADR-000397)
	// so recap-worker fetches tags directly from the data owner instead
	// of reading alt_db tables through tag-generator.
	// Origin: services.backend.v1.BackendInternalService/BatchGetTagsByArticleIDs
	BatchGetTagsByArticleIDs(context.Context, *connect.Request[v1.BatchGetTagsByArticleIDsRequest]) (*connect.Response[v1.BatchGetTagsByArticleIDsResponse], error)
	// DeleteArticleSummary deletes an article summary by article ID.
	// Origin: services.backend.v1.BackendInternalService/DeleteArticleSummary
	//
	// KNOWN CONFLICT with the append-first invariant (capability catalog §4-6).
	// Recorded here rather than resolved, because resolving it is a behaviour
	// change and this batch made none.
	//
	// This is a physical DELETE, and it is the only destructive write on the
	// summary domain that this service offers. The versioned half —
	// CreateSummaryVersion / MarkSummaryVersionSuperseded, added by Wave 3
	// batch 5 — never overwrites and never removes: a bad summary is superseded
	// and the old row stays readable so a reprojection can still resolve it. Two
	// models for one concept now sit side by side in this contract:
	// article_summaries is destructively mutable, summary_versions is
	// append-only.
	//
	// The consequence is concrete, not stylistic. When the quality checker
	// deletes a summary here, summary_versions still holds every version of it,
	// so the two stores disagree about whether that article was ever
	// summarised — and which one is right depends on which question is asked.
	// A data plane whose job is to hold the append-first line should not also
	// be the thing that breaks it.
	//
	// The resolution on the table (catalog §4-6) is to treat article_summaries
	// as a disposable projection of summary_versions and retire this procedure,
	// which would make the delete a supersede. That belongs to whoever owns
	// article_summaries next; until then, this comment is the record that the
	// contradiction is known rather than overlooked.
	DeleteArticleSummary(context.Context, *connect.Request[v1.DeleteArticleSummaryRequest]) (*connect.Response[v1.DeleteArticleSummaryResponse], error)
	// CheckArticleSummaryExists checks if an article summary exists.
	// Origin: services.backend.v1.BackendInternalService/CheckArticleSummaryExists
	CheckArticleSummaryExists(context.Context, *connect.Request[v1.CheckArticleSummaryExistsRequest]) (*connect.Response[v1.CheckArticleSummaryExistsResponse], error)
	// FindArticlesWithSummaries returns articles with summaries for quality checking.
	// Origin: services.backend.v1.BackendInternalService/FindArticlesWithSummaries
	FindArticlesWithSummaries(context.Context, *connect.Request[v1.FindArticlesWithSummariesRequest]) (*connect.Response[v1.FindArticlesWithSummariesResponse], error)
	// ListUnsummarizedArticles returns articles without summaries for polling-based summarization.
	// Origin: services.backend.v1.BackendInternalService/ListUnsummarizedArticles
	ListUnsummarizedArticles(context.Context, *connect.Request[v1.ListUnsummarizedArticlesRequest]) (*connect.Response[v1.ListUnsummarizedArticlesResponse], error)
	// HasUnsummarizedArticles checks if any articles lack summaries.
	// Origin: services.backend.v1.BackendInternalService/HasUnsummarizedArticles
	HasUnsummarizedArticles(context.Context, *connect.Request[v1.HasUnsummarizedArticlesRequest]) (*connect.Response[v1.HasUnsummarizedArticlesResponse], error)
	// GetEmptyFeedID returns a feed ID that has no articles for the given feed URL.
	// Returns empty feed_id if all feeds for this URL already have articles.
	// Origin: services.backend.v1.BackendInternalService/GetEmptyFeedID
	GetEmptyFeedID(context.Context, *connect.Request[v1.GetEmptyFeedIDRequest]) (*connect.Response[v1.GetEmptyFeedIDResponse], error)
	// FetchTagCloud returns tag names with article counts for topic exploration.
	// Origin: services.backend.v1.BackendInternalService/FetchTagCloud
	FetchTagCloud(context.Context, *connect.Request[v1.FetchTagCloudRequest]) (*connect.Response[v1.FetchTagCloudResponse], error)
	// FetchArticlesByTag returns articles filtered by tag name.
	// Origin: services.backend.v1.BackendInternalService/FetchArticlesByTag
	FetchArticlesByTag(context.Context, *connect.Request[v1.FetchArticlesByTagRequest]) (*connect.Response[v1.FetchArticlesByTagResponse], error)
	// ListRecapArticles returns paginated articles within a time window.
	// Service-to-service only; auth is established at the mTLS transport layer.
	// Origin: services.backend.v1.BackendInternalService/ListRecapArticles
	ListRecapArticles(context.Context, *connect.Request[v1.ListRecapArticlesRequest]) (*connect.Response[v1.ListRecapArticlesResponse], error)
	// GetSystemUser returns the first Kratos identity id.
	// Origin: GET /v1/internal/system-user (REST). Called by pre-processor.
	GetSystemUser(context.Context, *connect.Request[v1.GetSystemUserRequest]) (*connect.Response[v1.GetSystemUserResponse], error)
	// ListRecentArticles returns articles published within a time window.
	// Origin: GET /v1/internal/articles/recent (REST). Called by
	// rag-orchestrator for its temporal topics feature.
	ListRecentArticles(context.Context, *connect.Request[v1.ListRecentArticlesRequest]) (*connect.Response[v1.ListRecentArticlesResponse], error)
	// ClaimOutboxBatch takes ownership of up to `limit` PENDING rows and marks
